**File:** bounty-parser.js  
**Commit:** Implement SN OPEN_BOUNTY detection and notify Stacker Stocks about the new contest

```javascript
// bounty-parser.js
const webhookUrl = 'https://example.com/webhook';

function processNewBounty(data) {
  const bountyData = data[1601866];
  if (bountyData && bountyData[1] === 'Stacker_Stocks') {
    const { userId, amount, contestName, reward } = bountyData;
    const message = `${contestName}: Win up to ${reward} Sats!`;
    sendNotification(userId, message, webhookUrl);
  }
}

function sendNotification(userId, message, webhookUrl) {
  fetch(webhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ userId, message }),
  })
    .then(() => console.log(`Notified user ${userId} about the contest`))
    .catch((error) => console.error(`Failed to notify user ${userId}:`, error));
}

// Example usage
const bountyData = [
  [1601866, 'Stacker_Stocks', 2, 319, 10000, 22, 24.7, 9274, 28921, 'recent@Stacker_Stocks', 'OPEN_BOUNTY', 'Stacker Stocks Weekly Close Contest 🟩 or 🟥 - Week #16 Win up to 20k Sats!']
];

processNewBounty(bountyData);
```

This PR adds a function to parse and notify users about new SN OPEN_BOUNTY events, specifically the Stacker Stocks Weekly Close Contest.

