#### 3. Immediate Resolution of Issue #1339: Contest Prediction Dispatcher
For Stacker News item `#1601866` (*"Stacker Stocks Weekly Close Contest 🟩 or 🟥 - Week #16 Win up to 20k Sats!"*), provide a submission automation script in [`scripts/sn_contest_solver.mjs`](file:///scripts/sn_contest_solver.mjs) that fetches the target stock/index symbol, retrieves the Friday closing price benchmark, formats the directional forecast comment (🟩 Green or 🟥 Red) with cryptographic sat payout invoice, and claims the 10,000 sat reward.

---

### What alternative solutions did you explore? (Optional)

1. **GitHub Issues Search API (`octokit.rest.search.issuesAndPullRequests`)**:
   - *Exploration*: Dynamically searching GitHub issues on every run using `q: repo:owner/repo is:issue is:open label:bounty ...`.
   - *Drawback*: The GitHub Search API is subject to secondary rate limits (30 requests/minute) and exhibits a 10–60 second search indexing latency. In overlapping cron runs, index delay allows race conditions where two workflows query GitHub before the first issue is indexed, opening duplicates like #1338 and #1339.
   - *Selected approach*: Storing the seen IDs in `data/sn_targets_accumulated/alerted_bounties.tsv` and committing it via Git provides atomic, local, zero-API-cost deduplication, with `issues.listForRepo` serving as a resilient secondary defense.

2. **Single Pinned Issue Dashboard (Updating a Single Issue)**:
   - *Exploration*: Editing a single pinned GitHub Issue with an active markdown table of current open bounties instead of creating individual issues.
   - *Drawback*: Prevents webhook triggers, individual PR linkage, granular comment discussions, and bounty-specific notification routing. Having one deterministic issue per Stacker News item ID preserves clear traceability while preventing runaway spam.

---

### What automated tests can you add to prevent this from re-occurring?

Add a comprehensive unit test suite in [`tests/sn_radar_dedup.test.mjs`](file:///tests/sn_radar_dedup.test.mjs) using Node.js built-in test runner (`node --test`):

```javascript
import { test, describe, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

describe('Stacker News Radar Bounty Deduplication Suite', () => {
  let tmpDir;
  let ledgerPath;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'sn-radar-test-'));
    ledgerPath = path.join(tmpDir, 'alerted_bounties.tsv');
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  function filterNewBounties(ledgerFile, incomingRows) {
    const seen = new Set();
    if (fs.existsSync(ledgerFile)) {
      const lines = fs.readFileSync(ledgerFile, 'utf8').split('\n');
      for (const line of lines) {
        if (!line.trim() || line.startsWith('#')) continue;
        const cols = line.split('\t');
        if (cols[1]) seen.add(cols[1].trim());
      }
    } else {
      fs.writeFileSync(ledgerFile, '# discovered_at\tid\tsub\ttier\tscore\tbounty\n');
    }

    const newRows = [];
    for (const row of incomingRows) {
      const cols = row.split('\t');
      const id = cols[0];
      if (id && !seen.has(id)) {
        newRows.push(row);
        seen.add(id);
        fs.appendFileSync(ledgerFile, `${new Date().toISOString()}\t${row}\n`);
      }
    }
    return newRows;
  }

  test('detects newly discovered bounty on first run', () => {
    const mockRow = '1601866\tStacker_Stocks\t2\t319\t10000\t22\t24.7\t9274\t28921\trecent@Stacker_Stocks\tOPEN_BOUNTY\tStacker Stocks Weekly Close Contest';
    const newItems = filterNewBounties(ledgerPath, [mockRow]);

    assert.equal(newItems.length, 1);
    assert.equal(newItems[0].split('\t')[0], '1601866');
    assert.ok(fs.existsSync(ledgerPath));
  });

  test('strictly rejects duplicate bounty on subsequent cron executions', () => {
    const mockRow = '1601866\tStacker_Stocks\t2\t319\t10000\t22\t24.7\t9274\t28921\trecent@Stacker_Stocks\tOPEN_BOUNTY\tStacker Stocks Weekly Close Contest';

    // First execution (e.g. Issue #1338 run)
    const run1 = filterNewBounties(ledgerPath, [mockRow]);
    assert.equal(run1.length, 1);

    // Second execution 34 seconds later (e.g. Issue #1339 run)
    const run2 = filterNewBounties(ledgerPath, [mockRow]);
    assert.equal(run2.length, 0, 'Must not emit duplicate bounty that was already alerted');

    // Third execution on next 15-minute cron interval
    const run3 = filterNewBounties(ledgerPath, [mockRow]);
    assert.equal(run3.length, 0, 'Must suppress repeating open bounties across all cron intervals');
  });

  test('allows new independent bounty ID while suppressing existing', () => {
    const bountyA = '1601866\tStacker_Stocks\t2\t319\t10000\t22\t24.7\t9274\t28921\trecent@Stacker_Stocks\tOPEN_BOUNTY\tStacker Stocks Contest';
    const bountyB = '1602999\tbitcoin\t1\t500\t50000\t5\t1.2\t1234\t567\trecent@bitcoin\tOPEN_BOUNTY\tLightning Node Debugging';

    filterNewBounties(ledgerPath, [bountyA]);

    const mixedRun = filterNewBounties(ledgerPath, [bountyA, bountyB]);
    assert.equal(mixedRun.length, 1);
    assert.equal(mixedRun[0].split('\t')[0], '1602999', 'Only the new unalerted bounty ID should be accepted');
  });
});
```
